-- ═══════════════════════════════════════════════════════════════════════════
--  HRC — استرجاع نسخة محمولة
--  أُنشئت في : 2026-11-15T12:00:00.000Z
--  البصمة    : hash
--  الأعداد   : {"jobs":47,"applicants":440,"job_attempts":880,"audit_log":1240,"staff":3}
--
--  ⚠ لا تُشغّل هذا الملف على قاعدة فيها بيانات — يبدأ بـ TRUNCATE.
--  ⚠ استرجعه على قاعدة جديدة أولاً، وتحقّق من الأعداد قبل نقلها للإنتاج.
--  ⚠ يجب أن يكون مخطط brc منشأً قبل التنفيذ (docs/schema.sql أو الهجرات).
-- ═══════════════════════════════════════════════════════════════════════════

SET client_encoding = 'UTF8';
DO $$ BEGIN SET LOCAL session_replication_role = replica;
EXCEPTION WHEN insufficient_privilege OR others THEN NULL; END $$;

BEGIN;

CREATE SCHEMA IF NOT EXISTS brc;

-- إفراغ بنفس ترتيب المفاتيح الأجنبية
-- ⚠ brc.staff ليست هنا بقصد: تفريغها يحذف حساب المدير الذي ينفّذ هذا
--   السكربت، فيفقد الدخول. الحسابات تُضاف بـ ON CONFLICT DO NOTHING.
TRUNCATE brc.job_attempts, brc.applicants, brc.jobs, brc.employer_job_credentials, brc.issued_serials, brc.card_number_registry, brc.audit_log, brc.settings RESTART IDENTITY CASCADE;

-- 3 حساباً في brc.staff (بلا كلمات مرور — تُنشأ في Authentication)
-- ON CONFLICT: لا نطمس حساباً موجوداً على المشروع الجديد
ON CONFLICT ("username") DO NOTHING;

-- 440 صفاً في applicants (20 عموداً)

-- 47 صفاً في jobs (15 عموداً)
COMMIT;
